STORY = [('taeho', '드디어 너희들 업무 배정하는 날이다.', 'Finally, it is the day to assign your tasks.', [(296, '드디어 너희들 업무 배정하는 날이다')], ''), ('taeho', '그 다음은 백승찬이.', 'Next up is Baek Seung-chan.', [(307, '그 다음은 백승찬이')], ''), ('taeho', '1지망이 연예가중계야?', 'Your first choice is Entertainment Weekly?', [(308, '일지망이'), (309, '연애가중계야?')], 'Fixes 연애 to 연예.'), ('taeho', '특이하네. 기특해.', 'That is unusual. Admirable.', [(311, '특이하네 기특해')], ''), ('taeho', '신입이 연예가중계 지망하고, 네가 처음이야.', 'A rookie applying for Entertainment Weekly, you are the first.', [(312, '신입이 연애가중계 지망하고'), (313, '네가 처음이야 그거 아주 고생하는 프로라서 애들이 안 하려고 하거든')], 'Shortened to focus on the main point and fixes typo.'), ('seungchan', '열심히 하겠습니다.', 'I will work hard.', [(314, '열심히 하겠습니다')], ''), ('taeho', '그래. 너는 1박 2일.', 'Okay. You get 2 Days and 1 Night.', [(315, '그래 너는 1박 2일')], ''), ('taeho', '그 팀 지금 분위기가 뭐 그렇게 좋진 않을 거야.', "The atmosphere in that team probably isn't that great right now.", [(316, '그 팀 지금 분위기가 뭐 그렇게 좋진 않을 거야')], ''), ('taeho', '가서 네가 선배님들 기분 좀 업시켜 드리고.', 'Go and cheer up the seniors a bit.', [(317, '가서 네가 선배님들 기분 좀 업 시켜드리고')], '')]

WALK = [(0, None, "'Tae-ho starts with excitement.'"), (1, None, "'He calls the next rookie.'"), (2, None, "'He reads Seung-chan's application.'"), (3, None, "'He sounds impressed.'"), (4, None, "'He praises the rookie's bravery.'"), (5, None, "'Seung-chan bows proudly.'"), (6, None, "'Tae-ho pulls the rug out.'"), (7, None, "'He gives a subtle warning.'"), (8, None, "'He gives the rookie an impossible task.'")]
